  local function _c_scanLiftNames()local cr=workspace:FindFirstChild('Canopy Ride')if not cr then
    return{'Lift1','Lift2','Lift4','Lift5','Lift6'}
  end
  local names={}for _,child in ipairs(cr:GetChildren())do
