      elseif _HM_EN_STF and _HM_SET_STF[self] then
        extra = _HM_EX_STF
      elseif _HM_EN_LAGSVR and _HM_SET_LAGSVR[self] then
        extra = _HM_EX_LAGSVR
      elseif _HM_EN_SUBMITVOTE and _HM_SET_SUBMITVOTE[self] then
        extra = _HM_EX_SUBMITVOTE
      elseif _HM_EN_REQPROFILE and _HM_SET_REQPROFILE[self] then
        extra = _HM_EX_REQPROFILE
      end
      if extra > 0 then
        local a1, a2 = ...
        if method == "InvokeServer" then
          for _ = 1, extra do
            task.spawn(origNC, self, a1, a2)
          end
        else
          for _ = 1, extra do
