      end
      capBtn.BackgroundColor3 = Palette.Btn.Active
      if capEntry.seatPart and capEntry.seatPart.Parent then
        _activePianoSeat = capEntry.seatPart
        BENCH_POS = capEntry.seatPart.Position
        if selectedPianoLbl then
          selectedPianoLbl.Text = "  Selected: " .. capEntry.name
          .. "  |  Seat: " .. capEntry.seatPart.Name
          selectedPianoLbl.TextColor3 = Color3.fromRGB(220, 220, 220)
        end
        SetStatus("[PIANO] " .. capEntry.name .. " selected \226\128\148 click TELEPORT & SIT.", Color3.fromRGB(220, 220, 220))
      else
        _activePianoSeat = nil
        BENCH_POS = capEntry.pianoPos + Vector3.new(0, 3, 3)
        if selectedPianoLbl then
          selectedPianoLbl.Text = "  Selected: " .. capEntry.name .. "  |  (no seat \226\128\148 TP in front of piano)"
          selectedPianoLbl.TextColor3 = Color3.fromRGB(170, 170, 170)
        end
        SetStatus("[PIANO] " .. capEntry.name .. " \226\128\148 no seat found. TP in front of piano.", Color3.fromRGB(175, 175, 175))
      end
    end
    )
    table.insert(pianoListBtns, btn)
  end
  end
