        respawnStatusLbl.Text = "  No SpawnLocation found on this map."
        respawnStatusLbl.TextColor3 = Color3.fromRGB(130, 130, 130)
        SetStatus("[SPAWN] No SpawnLocation found.", Color3.fromRGB(155, 155, 155))
        return
      end
      local nearest = pts[1]
      _respawnPos = nearest.part.Position
      _respawnCFrame = nearest.part.CFrame
      respawnStatusLbl.Text = "  Spawn: " .. nearest.label .. "  (~" .. math.floor(nearest.dist) .. " studs)"
      respawnStatusLbl.TextColor3 = Color3.fromRGB(215, 215, 215)
      SetStatus("[SPAWN] " .. #pts .. " task.spawn(s) found \226\128\148 nearest: " .. nearest.part.Name, Color3.fromRGB(220, 220, 220))
    end
    )
  end
  )
