  local function RefreshRemoteList()
    for _, b in ipairs(remoteListBtns) do
      pcall(function() b:Destroy()
      end
      )
    end
    remoteListBtns = {}
    if #foundRemotes == 0 then
      scanStatusLbl.Text = "  No piano remote found. Try entering a piano game then scan."
      scanStatusLbl.TextColor3 = Color3.fromRGB(130, 130, 130)
      return
    end
    scanStatusLbl.Text = "  Found " .. #foundRemotes .. " remote(s). Click to select (max 2):"
    scanStatusLbl.TextColor3 = Color3.fromRGB(220, 220, 220)
    local _slotColors = { Color3.fromRGB(235, 235, 235), Color3.fromRGB(205, 205, 205) }
    local _slotBgs = { Palette.ElementActive, Palette.ElementHover }
    local _slotStroke = { Color3.fromRGB(190, 190, 190), Color3.fromRGB(150, 150, 150) }
    local _REMOTE_IDLE_BG = Palette.Home.Tile
    local _REMOTE_IDLE_STROKE = Palette.StrokeSoft
    local function _getSlot(remote)
      for si, r in ipairs(pianoRemotes) do
        if r == remote then
          return si
        end
      end
      return nil
    end
    local function _updateSelectedLbl()
      local names = {}
      for _, r in ipairs(pianoRemotes) do
        pcall(function() table.insert(names, r.Name)
        end
        )
      end
      if #names == 0 then
        selectedRemoteLbl.Text = "  Active: \226\128\148 (none selected)\n  Click 1 or 2 remotes from the list (max 2 simultaneous)"
        selectedRemoteLbl.TextColor3 = Color3.fromRGB(190, 190, 190)
      elseif #names == 1 then
        selectedRemoteLbl.Text = "  [1] \226\151\136 " .. names[1] .. "\n  (optional: pick 1 more remote for dual-fire)"
        selectedRemoteLbl.TextColor3 = _slotColors[1]
      else
        selectedRemoteLbl.Text = "  [1] \226\151\136 " .. names[1] .. "  +  [2] \226\151\136 " .. names[2]
        selectedRemoteLbl.TextColor3 = Color3.fromRGB(210, 210, 210)
      end
    end
    local function _repaintBtns()
      for bi, b in ipairs(remoteListBtns) do
        local entry = foundRemotes[bi]
        if entry then
          local si = _getSlot(entry.remote)
          pcall(function()
            Tween(b, 0.15, nil, nil, { BackgroundColor3 = si and _slotBgs[si] or _REMOTE_IDLE_BG })
            b.TextColor3 = si and _slotColors[si] or Palette.SubText
            Stroke(b, si and _slotStroke[si] or _REMOTE_IDLE_STROKE, 1, si and 0.45 or 1)
          end
          )
        end
      end
    end
    for i, entry in ipairs(foundRemotes) do
      local si0 = _getSlot(entry.remote)
      local btnBg = si0 and _slotBgs[si0] or _REMOTE_IDLE_BG
      local btnCol = si0 and _slotColors[si0] or Palette.SubText
      local slotTag = si0 and ("[" .. si0 .. "]  ") or ""
      local kwHint = entry.matches ~= "" and entry.matches or "no kw match"
      local btn = New("TextButton", {
        Size = UDim2.new(1, 0, 0, 40),
        BackgroundColor3 = btnBg,
        Font = Enum.Font.GothamMedium,
        Text = "",
        AutoButtonColor = false,
        LayoutOrder = i,
        Parent = remoteListFrame,
      })
      Round(btn, 10)
      local btnStroke = Stroke(btn, si0 and _slotStroke[si0] or _REMOTE_IDLE_STROKE, 1, si0 and 0.45 or 1)
      local btnDot = New("Frame", {
        Size = UDim2.new(0, 6, 0, 6),
        Position = UDim2.new(0, 10, 0.5, -3),
        BackgroundColor3 = si0 and _slotColors[si0] or Palette.TextMuted,
        BorderSizePixel = 0,
        Parent = btn,
      })
      New("UICorner", { CornerRadius = UDim.new(1, 0), Parent = btnDot })
      New("TextLabel", {
        Text = slotTag .. "[" .. entry.kind .. "]  " .. entry.path,
        Font = Enum.Font.GothamBold,
        TextSize = 11,
        TextColor3 = btnCol,
        BackgroundTransparency = 1,
        Position = UDim2.new(0, 22, 0, 6),
        Size = UDim2.new(1, -32, 0, 14),
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
        Parent = btn,
      })
      New("TextLabel", {
        Text = kwHint,
        Font = Enum.Font.Gotham,
        TextSize = 9,
        TextColor3 = Palette.TextMuted,
        BackgroundTransparency = 1,
        Position = UDim2.new(0, 22, 0, 22),
        Size = UDim2.new(1, -32, 0, 12),
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
        Parent = btn,
      })
      SafeConnect(GetSignal(btn, "MouseEnter"), function()
        if not _getSlot(entry.remote) then
          Tween(btn, 0.1, nil, nil, { BackgroundColor3 = Palette.GlassLight })
        end
      end
      )
      SafeConnect(GetSignal(btn, "MouseLeave"), function()
        if not _getSlot(entry.remote) then
          Tween(btn, 0.1, nil, nil, { BackgroundColor3 = _REMOTE_IDLE_BG })
        end
      end
      )
      local capturedEntry = entry
      SafeConnect(GetSignal(btn, "MouseButton1Click"), function()
        PlayUISound("Click")
        local existSlot = _getSlot(capturedEntry.remote)
        if existSlot then
          table.remove(pianoRemotes, existSlot)
        elseif #pianoRemotes < 2 then
          table.insert(pianoRemotes, capturedEntry.remote)
        else
          pianoRemotes[2] = capturedEntry.remote
        end
        _HM_RebuildPianoSet()
        _repaintBtns()
        _updateSelectedLbl()
        local names = {}
        for _, r in ipairs(pianoRemotes) do
          pcall(function() table.insert(names, r.Name)
          end
          )
        end
        if #names > 0 then
          SetStatus("[REMOTE] " .. table.concat(names, " + ") .. " active. Ready to spam!", Color3.fromRGB(220, 220, 220))
        else
          SetStatus("[REMOTE] All remotes deselected.", Color3.fromRGB(190, 190, 190))
        end
      end
      )
      table.insert(remoteListBtns, btn)
    end
    if #pianoRemotes == 0 and #foundRemotes > 0 then
      table.insert(pianoRemotes, foundRemotes[1].remote)
      _HM_RebuildPianoSet()
      _repaintBtns()
      _updateSelectedLbl()
    end
  end
