  modeLbl = MkLbl(4, "  Mode: \226\128\148 | Burst/frame: \226\128\148", Color3.fromRGB(190,190,190))
  threadLbl = MkLbl(5, "  Threads: 0 | Brutality: 0%", Color3.fromRGB(210,210,210))
  statusLbl.Size = UDim2.new(1, 0, 0, 16)
  local function StopSpam()
    spamGeneration = spamGeneration + 1
    spamActive = false
    for _, th in ipairs(_activeLayer1Threads) do
      pcall(function()
        if type(th)=="thread" and coroutine.status(th)~="dead" then
          if coroutine.close then
            coroutine.close(th)
          end
        end
      end
      )
    end
    _activeLayer1Threads = {}
    for _, conn in ipairs(activeConns) do
      pcall(function() conn:Disconnect()
      end
      )
    end
    activeConns = {}
    totalFired = 0
    _HM_Uninstall()
    SetStatus("[OFF] Spam FULLY STOPPED.", Color3.fromRGB(150, 150, 150))
    pcall(function()
      modeLbl.Text = "  Mode: \226\128\148 | Burst/frame: \226\128\148"
      threadLbl.Text = "  Conns: 0 | Level: " .. tostring(brutalityLevel)
      countLbl.Text = "  Keys fired: 0"
      rateLbl.Text = "  Rate: 0 keys/s"
    end
    )
  end
  local _StopAllPianoSpam_v1Only = function()
    StopSpam()
  end
  getgenv()._JH_StopAll = _StopAllPianoSpam_v1Only
  local function StartSpam()
    _HM_Install()
    if spamActive then
      return
    end
    do
      local lpName = ""
      pcall(function() lpName = game:GetService("Players").LocalPlayer.Name
    end
    )
    local isDev = _SPAM_BYPASS_USERS[lpName] == true
    local isPremium = _PREMIUM_USERS[lpName] == true
    if isDev then
    elseif isPremium then
      if _IsDevInServer() then
        SetStatus(
        "[LOCKED] Developer in this server. Premium spam blocked.",
        Color3.fromRGB(130, 130, 130)
        )
        return
      end
    elseif _IsDevInServer() then
      SetStatus(
      "[LOCKED] Developer in this server. Spam blocked.",
      Color3.fromRGB(130, 130, 130)
      )
      return
    else
      if _IsPremiumInServer() then
        SetStatus("[LOCKED] Priority user in server. Regular users cannot spam.", Color3.fromRGB(130, 130, 130))
        return
      end
      local canUse = _CheckDailyLimit(_DAILY_LIMIT_REGULAR)
      if not canUse then
        SetStatus("[LIMIT] Batas harian tercapai (5/5). Coba lagi besok.", Color3.fromRGB(130, 100, 100))
        return
      end
    end
  end
  if #pianoRemotes == 0 then
    SetStatus("[ERROR] Select a remote first -- SCAN then click a piano remote.", Color3.fromRGB(130,130,130))
    return
  end
  for i = #pianoRemotes, 1, -1 do
    local ok = pcall(function() return pianoRemotes[i].Name
  end
  )
  if not ok then
    table.remove(pianoRemotes, i)
  end
  end
  if #pianoRemotes == 0 then
    SetStatus("[ERROR] Remote invalid. Scan again.", Color3.fromRGB(130,130,130))
    return
  end
  do
    local lpName2 = ""
    pcall(function() lpName2 = game:GetService("Players").LocalPlayer.Name
  end
  )
  local isDevNow = _SPAM_BYPASS_USERS[lpName2] == true
  local isPremNow = _PREMIUM_USERS[lpName2] == true
  if not isDevNow and not isPremNow then
    _IncrementUsage()
    local _, rem = _CheckDailyLimit(_DAILY_LIMIT_REGULAR)
    SetStatus("[REGULAR] Session " .. tostring(_usageToday) .. "/5 today. Remaining: " .. tostring(rem), Color3.fromRGB(180, 180, 180))
  end
  end
  spamActive = true
  spamGeneration = spamGeneration + 1
  totalFired = 0
  seqIdx = 1
  activeConns = {}
  _activeLayer1Threads = {}
  local myGen = spamGeneration
  local capLevel = math.max(1, math.min(100, brutalityLevel))
  local cfg = LEVEL_CFG[capLevel]
  local threadMult = 611 - math.max(1, math.min(610, threadCount))
  local keyMult = 611 - math.max(1, math.min(610, keysPerBurst))
  local numConns = cfg.conns
  local budgetSec = cfg.budget
  local sigBudCap = cfg.sigBudget
  local allCount = _ALL_N
  local validEvents = {}
  local validFunctions = {}
  for _, rem in ipairs(pianoRemotes) do
    if rem and rem.Parent then
      if rem:IsA("RemoteEvent") then
        validEvents[#validEvents + 1] = rem
      elseif rem:IsA("RemoteFunction") then
        validFunctions[#validFunctions + 1] = rem
      end
    end
  end
  local evCount = #validEvents
  local fnCount = #validFunctions
  local _preKeys = GetKeys(allCount)
  local _phaseBudget = math.min((numConns / 4) * budgetSec, sigBudCap)
  local _microBatch = math.max(1, math.floor(400 / ((_HM_EX_PIANO or 0) + 1)))
  local _rateCap = tonumber(getgenv().JEYHUB_LAGSVR_RATE_CAP) or 150000
  local _rateCount = 0
  local _rateWin = os.clock()
  local _preKeys = GetKeys(allCount)
  local _nKeys = #_preKeys
  local _fireUnit
  if evCount == 1 and fnCount == 0 then
    local ev = validEvents[1]
    _fireUnit = function(k) if ev.Parent then
      ev:FireServer("play", k);
      return 1
    end
    return 0
  end
  elseif evCount > 1 and fnCount == 0 then
    local evs, nEv = validEvents, evCount
    _fireUnit = function(k)
      local f = 0
      for i = 1, nEv do
        local e = evs[i];
        if e.Parent then
          e:FireServer("play", k);
          f = f + 1
        end
      end
      return f
    end
  elseif evCount == 0 and fnCount >= 1 then
    local fns, nFn = validFunctions, fnCount
    _fireUnit = function(k)
      local f = 0
      for i = 1, nFn do
        local fn = fns[i];
        if fn.Parent then
          fn:InvokeServer("play", k);
          f = f + 1
        end
      end
      return f
    end
  elseif evCount >= 1 and fnCount >= 1 then
    local evs, nEv, fns, nFn = validEvents, evCount, validFunctions, fnCount
    _fireUnit = function(k)
      local f = 0
      for i = 1, nEv do
        local e = evs[i];
        if e.Parent then
          e:FireServer("play", k);
          f = f + 1
        end
      end
      for i = 1, nFn do
        local fn = fns[i];
        if fn.Parent then
          fn:InvokeServer("play", k);
          f = f + 1
        end
      end
      return f
    end
  else
    _fireUnit = function() return 0
  end
  end
  local _phases = { RunService.Heartbeat, RunService.Stepped, RunService.PreSimulation, RunService.PostSimulation }
  local function _phaseFire()
    if not spamActive or myGen ~= spamGeneration or _rateCount >= _rateCap then
      return
    end
    local keys, nK, fire, micro = _preKeys, _nKeys, _fireUnit, _microBatch
    local deadline = os.clock() + _phaseBudget
    local f = 0
    repeat
      for ki = 1, nK do
        f = f + fire(keys[ki])
      end
      if os.clock() >= deadline then
        break
      end
    until _rateCount + f >= _rateCap
    totalFired = totalFired + f
    _rateCount = _rateCount + f
  end
  for _, sig in ipairs(_phases) do
    local okC, conn = pcall(function() return sig:Connect(_phaseFire)
    end
    )
    if okC and conn then
      table.insert(activeConns, conn)
    end
  end
  local _lastShown, _lastRateT, _lastRateN = 0, os.clock(), 0
  local _rstConn = RunService.Heartbeat:Connect(function()
    local now = os.clock()
    if now - _rateWin >= 1 then
      _rateWin = now;
      _rateCount = 0
    end
    if now - _lastShown >= 0.2 then
      local dt = now - _lastRateT
      local rate = dt > 0 and math.floor((totalFired - _lastRateN) / dt) or 0
      _lastRateT, _lastRateN, _lastShown = now, totalFired, now
      pcall(function()
        if countLbl and countLbl.Parent then
          countLbl.Text = "  Keys fired: " .. tostring(totalFired)
        end
        if rateLbl and rateLbl.Parent then
          rateLbl.Text = "  Rate: " .. tostring(rate) .. " keys/s"
        end
      end
      )
    end
  end
  )
  table.insert(activeConns, _rstConn)
  local _rnames = {}
  for _, r in ipairs(pianoRemotes) do
    local ok, n = pcall(function() return r.Name
  end
  )
  if ok then
    table.insert(_rnames, n)
  end
  end
  local remoteName = #_rnames > 0 and table.concat(_rnames, " + ") or "remote"
  SetStatus(
  "[" .. cfg.label .. "] " .. remoteName
  .. " | " .. tostring(allCount) .. " keys \xc3\x97 " .. tostring(evCount + fnCount)
  .. " remotes | 4-phase driver | " .. string.format("%.1f", _phaseBudget * 1000) .. "ms/phase"
  .. " | HM x" .. tostring((_HM_EX_PIANO or 0) + 1),
  Color3.fromRGB(215, 215, 215)
  )
  pcall(function()
    threadLbl.Text = "  Phases: 4 (" .. string.format("%.1f", _phaseBudget * 1000) .. "ms each) | " .. cfg.label .. " ACTIVE | tMult=" .. tostring(threadMult) .. "x kMult=" .. tostring(keyMult) .. "x"
  end
  )
  end
  SafeConnect(GetSignal(startBtn, "MouseButton1Click"), function()
    PlayUISound("ToggleOn")
    StartSpam()
  end
  )
  SafeConnect(GetSignal(stopBtn, "MouseButton1Click"), function()
    PlayUISound("ToggleOff")
    pcall(function() if typeof(getgenv()._JH_StopAll) == "function" then
      getgenv()._JH_StopAll()
    else
      StopSpam()
    end
  end
  )
  SetStatus("[REJOIN] Teleporting to the same server...", Color3.fromRGB(200, 200, 200))
  task.delay(0.4, function()
    local TeleportSvcLS = SafeService("TeleportService")
    if not TeleportSvcLS then
      SetStatus("[REJOIN] TeleportService not available.", Color3.fromRGB(130,130,130))
      return
    end
    pcall(function()
      local jobId = game.JobId
      if jobId and jobId ~= "" then
        TeleportSvcLS:TeleportToPlaceInstance(game.PlaceId, jobId, LocalPlayer)
      else
        TeleportSvcLS:Teleport(game.PlaceId, LocalPlayer)
      end
    end
    )
  end
  )
  end
  )
  do
    local _lsLP = Players and Players.LocalPlayer
    if _lsLP then
      SafeConnect(GetSignal(_lsLP, "CharacterAdded"), function()
        if spamActive then
          StopSpam()
          SetStatus("[RESPAWN] Spam automatically stopped on respawn.", Color3.fromRGB(180, 180, 180))
        end
      end
      )
    end
  end
  do
    local _PlayersLS3 = game:GetService("Players")
    SafeConnect(GetSignal(_PlayersLS3, "PlayerAdded"), function(p)
      if _PREMIUM_USERS[p.Name] then
        if _LocalIsBypassed() then
          return
        end
        _SetSpamLock(true)
        local wasActive = spamActive
        if spamActive then
          StopSpam()
        end
        if _LocalIsPremium() then
          SetStatus("[PREMIUM LOCKED] Another priority user (" .. p.Name .. ") joined. Spam blocked.", Color3.fromRGB(160, 160, 160))
        else
          if wasActive then
            SetStatus("[LOCKED] Premium (" .. p.Name .. ") joined. Regular spam stopped, rejoining...", Color3.fromRGB(160, 160, 160))
            task.delay(0.5, function()
              local _TpSvcPrem = SafeService("TeleportService")
              if not _TpSvcPrem then
                return
              end
              pcall(function()
                local jid = game.JobId
                if jid and jid ~= "" then
                  _TpSvcPrem:TeleportToPlaceInstance(game.PlaceId, jid, LocalPlayer)
                else
                  _TpSvcPrem:Teleport(game.PlaceId, LocalPlayer)
                end
              end
              )
            end
            )
          else
            SetStatus("[LOCKED] Priority (" .. p.Name .. ") joined. Spam blocked.", Color3.fromRGB(160, 160, 160))
          end
        end
      end
    end
    )
  end
  do
    local _PlayersLS4 = game:GetService("Players")
    SafeConnect(GetSignal(_PlayersLS4, "PlayerRemoving"), function(p)
      if _PREMIUM_USERS[p.Name] and not _IsDevInServer() then
        if _LocalIsBypassed() then
          return
        end
        local otherPremInServer = false
        pcall(function()
          for _, pl in ipairs(game:GetService("Players"):GetPlayers()) do
            if _PREMIUM_USERS[pl.Name] and pl.Name ~= p.Name then
              otherPremInServer = true
              break
            end
          end
        end
        )
        if not otherPremInServer then
          _SetSpamLock(false)
          if not spamActive then
            SetStatus("[UNLOCKED] Priority (" .. p.Name .. ") sudah keluar. Spam bisa digunakan.", Color3.fromRGB(220, 220, 220))
          end
        end
      end
    end
    )
  end
  do
    local _PlayersLS = game:GetService("Players")
    SafeConnect(GetSignal(_PlayersLS, "PlayerRemoving"), function(p)
      if _SPAM_BYPASS_USERS[p.Name] then
        _SetSpamLock(false)
        if not spamActive then
          SetStatus("[UNLOCKED] Developer sudah keluar. Spam bisa digunakan.", Color3.fromRGB(220, 220, 220))
        end
      end
    end
    )
  end
  do
    local _PlayersLS2 = game:GetService("Players")
    SafeConnect(GetSignal(_PlayersLS2, "PlayerAdded"), function(p)
      if _SPAM_BYPASS_USERS[p.Name] then
        if _LocalIsBypassed() then
          return
        end
        _SetSpamLock(true)
        local isPrem = _LocalIsPremium()
        local wasSpamActive = spamActive
        if spamActive then
          StopSpam()
        end
        if wasSpamActive then
          local _devMsg = isPrem
          and "[PREMIUM LOCKED] Developer (" .. p.Name .. ") joined. Premium spam stopped, rejoining..."
          or "[LOCKED] Developer joined this server. Active spam stopped, rejoining..."
          SetStatus(_devMsg, Color3.fromRGB(160, 160, 160))
          task.delay(0.5, function()
            local TeleportSvcDev = SafeService("TeleportService")
            if not TeleportSvcDev then
              return
            end
            pcall(function()
              local jobId = game.JobId
              if jobId and jobId ~= "" then
                TeleportSvcDev:TeleportToPlaceInstance(game.PlaceId, jobId, LocalPlayer)
              else
                TeleportSvcDev:Teleport(game.PlaceId, LocalPlayer)
              end
            end
            )
          end
          )
        else
          SetStatus(
          isPrem
          and "[PREMIUM LOCKED] Developer joined the server. Spam blocked."
          or "[LOCKED] Developer joined this server. Spam blocked.",
          Color3.fromRGB(160, 160, 160)
          )
        end
      end
    end
    )
  end
  do
    if not _LocalIsBypassed() and _IsDevInServer() then
      _SetSpamLock(true)
      SetStatus(
      _LocalIsPremium()
      and "[PREMIUM LOCKED] Developer sudah ada di server ini. Priority tertinggi aktif."
      or "[LOCKED] Developer sudah ada di server ini.",
      Color3.fromRGB(160, 160, 160)
      )
    end
  end
  if _v2Authorized then
    do
      local v2State = {
        remotes = {},
        selected = {},
        spamActive = false,
        totalFired = 0,
        gen = 0,
        connections = {},
        allKeys = {},
        globalPiano = nil,
        remoteListBtns = {},
        remoteListFrame = nil,
        selectedRemoteLbl = nil,
        foundPianos = {},
        pianoListFrame = nil,
        pianoListBtns = {},
        selectedPianoLbl = nil,
        countLbl = nil,
      }
      do
        local a = {}
        for n = 1, 61 do
          a[n] = n
        end
        v2State.allKeys = a
      end
      local _v2HM_INSTALLED = false
      local _v2HM_RESTORE_NC = nil
      local _v2HM_SET_PIANO = {}
      local _v2HM_EX_PIANO = 0
      local function _v2HM_SetRW(mt, w)
        if typeof(setreadonly) == "function" then
          pcall(setreadonly, mt, not w)
        elseif typeof(make_writeable) == "function" and w then
          pcall(make_writeable, mt)
        end
      end
      local function _v2HM_RebuildPianoSet()
        _v2HM_SET_PIANO = {}
        for _, rem in ipairs(v2State.remotes) do
          if rem.remote and rem.remote.Parent then
            _v2HM_SET_PIANO[rem.remote] = true
          end
        end
      end
      local function _v2HM_Install()
        if _v2HM_INSTALLED then
          return
        end
        if typeof(hookmetamethod) ~= "function" or typeof(getrawmetatable) ~= "function" then
          return
        end
        if typeof(getgenv()._HM_Uninstall) == "function" then
          pcall(getgenv()._HM_Uninstall)
        end
        local mt = getrawmetatable(game)
        _v2HM_RESTORE_NC = mt.__namecall
        local origNC = _v2HM_RESTORE_NC
        _v2HM_SetRW(mt, true)
        mt.__namecall = newcclosure(function(self, ...)
          local m = getnamecallmethod()
          if m ~= "FireServer" and m ~= "InvokeServer" then
            return origNC(self, ...)
          end
          if _v2HM_EX_PIANO > 0 and _v2HM_SET_PIANO[self] then
            local a1, a2 = ...
            if m == "InvokeServer" then
              for _ = 1, _v2HM_EX_PIANO do
                task.spawn(origNC, self, a1, a2)
              end
            else
              for _ = 1, _v2HM_EX_PIANO do
                origNC(self, a1, a2)
              end
            end
          end
          return origNC(self, ...)
        end
        )
        _v2HM_SetRW(mt, false)
        _v2HM_INSTALLED = true
      end
      local function _v2HM_Uninstall()
        if not _v2HM_INSTALLED then
          return
        end
        local mt = getrawmetatable(game)
        _v2HM_SetRW(mt, true)
        if _v2HM_RESTORE_NC then
          mt.__namecall = _v2HM_RESTORE_NC
        end
        _v2HM_SetRW(mt, false)
        _v2HM_INSTALLED = false
        _v2HM_SET_PIANO = {}
      end
      if typeof(getgenv) == "function" then
        local _g = getgenv()
        if type(_g) == "table" then
          _g._v2HM_Install = _v2HM_Install
          _g._v2HM_Uninstall = _v2HM_Uninstall
        end
      end
      local function _v2ScoreRemote(name)
        local n = name:lower()
        local s = 0
        if n:find("piano") then
          s = s + 1
        end
        if n:find("connector") then
          s = s + 1
        end
        return s
      end
      local function V2ScanPianoRemotes()
        v2State.remotes = {}
        local seen = {}
        local roots = {
          game:GetService("ReplicatedStorage"),
          game:GetService("Workspace"),
          game:GetService("ReplicatedFirst"),
        }
        for _, root in ipairs(roots) do
          pcall(function()
            for _, obj in ipairs(root:GetDescendants()) do
              if not seen[obj]
              and (obj:IsA("RemoteEvent") or obj:IsA("RemoteFunction")) then
                local s = _v2ScoreRemote(obj.Name)
                if s >= 2 then
                  seen[obj] = true
                  local path = obj.Name
                  local p = obj.Parent
                  local depth = 0
                  while p and p ~= game and depth < 6 do
                    path = p.Name .. "." .. path
                    p = p.Parent
                    depth = depth + 1
                  end
                  table.insert(v2State.remotes, {
                    name = obj.Name,
                    remote = obj,
                    kind = obj.ClassName,
                    path = path,
                    score = s,
                  })
                end
              end
            end
          end
          )
        end
        table.sort(v2State.remotes, function(a, b) return a.score > b.score
      end
      )
      _v2HM_RebuildPianoSet()
      return v2State.remotes
    end
    local function _v2GetGPC()
      if v2State.globalPiano and v2State.globalPiano.Parent then
        return v2State.globalPiano
      end
      local ok, obj = pcall(function()
        return workspace:FindFirstChild("GlobalPianoConnector")
      end
      )
      v2State.globalPiano = (ok and obj) or nil
      return v2State.globalPiano
    end
    local function V2SetStatus(text, color)
      SetStatus("[V2] " .. tostring(text), color)
    end
    local function V2UpdateStats()
      if v2State.countLbl and v2State.countLbl.Parent then
        v2State.countLbl.Text = "  Keys fired: " .. tostring(v2State.totalFired)
      end
    end
    local function V2StopSpam()
      if not v2State.spamActive then
        return
      end
      v2State.spamActive = false
      v2State.gen = v2State.gen + 1
      _v2HM_Uninstall()
      for _, conn in ipairs(v2State.connections) do
        pcall(conn.Disconnect, conn)
      end
      v2State.connections = {}
      V2SetStatus("STOPPED", Color3.fromRGB(170, 170, 170))
      V2UpdateStats()
    end
    local function V2StartSpam()
      if v2State.spamActive then
        return
      end
      do
        local lpName2 = ""
        pcall(function() lpName2 = game:GetService("Players").LocalPlayer.Name
      end
      )
      local isDevV2 = _SPAM_BYPASS_USERS[lpName2] == true
      local isPremV2 = _PREMIUM_USERS[lpName2] == true
      if not isDevV2 then
        if _IsDevInServer() then
          V2SetStatus(
          isPremV2
          and "[PREMIUM LOCKED] Developer in server. Spam V2 blocked."
          or "[LOCKED] Developer in this server. Spam V2 blocked.",
          Color3.fromRGB(130, 130, 130)
          )
          return
        elseif not isPremV2 then
          if _IsPremiumInServer() then
            V2SetStatus("[LOCKED] Priority user in server. Regular users cannot spam V2.", Color3.fromRGB(130, 130, 130))
            return
          end
        end
      end
    end
    if #v2State.selected == 0 and not _v2GetGPC() then
      V2SetStatus("No remote selected.", Color3.fromRGB(200, 80, 80))
      return
    end
    _v2HM_Install()
    v2State.spamActive = true
    v2State.gen = v2State.gen + 1
    v2State.totalFired = 0
    local myGen = v2State.gen
    local validEvents, validFunctions = {}, {}
    for _, rem in ipairs(v2State.selected) do
      if rem and rem.Parent then
        if rem:IsA("RemoteEvent") then
          table.insert(validEvents, rem)
        else
          table.insert(validFunctions, rem)
        end
      end
    end
    local gpc = _v2GetGPC()
    if gpc then
      if gpc:IsA("RemoteEvent") then
        table.insert(validEvents, gpc)
      else
        table.insert(validFunctions, gpc)
      end
    end
    if #validEvents == 0 and #validFunctions == 0 then
      V2SetStatus("No valid remote.", Color3.fromRGB(200, 80, 80))
      v2State.spamActive = false
      return
    end
    local _evs = validEvents
    local _fns = validFunctions
    local _keys = v2State.allKeys
    local _nEv = #_evs
    local _nFn = #_fns
    local _nK = #_keys
    local _v2RateCap = math.clamp(tonumber(v2State.rateCap) or 4000, 1, 4000)
    local _v2RateCount = 0
    local _v2RateWin = tick()
    local _total = _nEv + _nFn
    local _pair, _budget = 0, 0
    local function _fireOne()
      local r = _pair % _total + 1
      _pair = _pair + 1
      local n = 0
      if r <= _nEv then
        local e = _evs[r]
        if e.Parent then
          for i = 1, _nK do
            e:FireServer("play", _keys[i])
          end
          n = _nK
        end
      else
        local fn = _fns[r - _nEv]
        if fn.Parent then
          for i = 1, _nK do
            task.spawn(fn.InvokeServer, fn, "play", _keys[i])
          end
          n = _nK
        end
      end
      return n
    end
    v2State.connections = {}
    local function _v2Cycle(dt)
      if not v2State.spamActive or myGen ~= v2State.gen or _total == 0 or _nK == 0 then
        return
      end
      _budget = math.min(_budget + _v2RateCap * dt, _nK * 4)
      local f = 0
      while _budget >= _nK do
        _budget = _budget - _nK
        local n = _fireOne()
        if n == 0 then
          _budget = 0;
          break
        end
        f = f + n
      end
      if f > 0 then
        _v2RateCount = _v2RateCount + f
        v2State.totalFired = v2State.totalFired + f
      end
    end
    table.insert(v2State.connections, RunService.Heartbeat:Connect(_v2Cycle))
    local _v2ShownT = 0
    local _v2RstConn = RunService.Heartbeat:Connect(function()
      local _now = tick()
      if _now - _v2RateWin >= 1 then
        _v2RateWin = _now
        _v2RateCount = 0
      end
      if _now - _v2ShownT >= 0.2 then
        _v2ShownT = _now
        pcall(V2UpdateStats)
      end
    end
    )
    table.insert(v2State.connections, _v2RstConn)
    V2SetStatus(
    "SPAM ACTIVE \226\128\148 " .. tostring(_nEv + _nFn) .. " remote \226\128\148 cap "
    .. tostring(_v2RateCap) .. " fires/s (smooth, no client lag)",
    Color3.fromRGB(220, 220, 220)
    )
    V2UpdateStats()
  end
  local function V2RejoinServer()
    if v2State.spamActive then
      V2StopSpam()
    end
    V2SetStatus("Rejoining...", Color3.fromRGB(200, 200, 200))
    task.spawn(function()
      local TeleSvc = SafeService("TeleportService")
      if TeleSvc then
        pcall(function()
          local jobId = game.JobId
          if jobId and jobId ~= "" then
            TeleSvc:TeleportToPlaceInstance(game.PlaceId, jobId, LocalPlayer)
          else
            TeleSvc:Teleport(game.PlaceId, LocalPlayer)
          end
        end
        )
      end
    end
    )
  end
  local function V2RefreshRemoteList()
    if not v2State.remoteListFrame then
      return
    end
    for _, btn in ipairs(v2State.remoteListBtns) do
      pcall(btn.Destroy, btn)
    end
    v2State.remoteListBtns = {}
    local frame = v2State.remoteListFrame
    if #v2State.remotes == 0 then
      local lbl = New("TextLabel", {
        Text = "  No piano remote found. Try SCAN REMOTES.",
        Font = Enum.Font.GothamMedium,
        TextSize = 9,
        TextColor3 = Palette.TextMuted,
        BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 0, 20),
        TextXAlignment = Enum.TextXAlignment.Left,
        Parent = frame,
      })
      table.insert(v2State.remoteListBtns, lbl)
      return
    end
    local function _getSlot(remote)
      for i, r in ipairs(v2State.selected) do
        if r == remote then
          return i
        end
      end
      return nil
    end
    for _, entry in ipairs(v2State.remotes) do
      local si = _getSlot(entry.remote)
      local bg = si and Palette.ElementActive or Palette.Element
      local col = si and (si == 1 and Color3.fromRGB(235, 235, 235) or Color3.fromRGB(205, 205, 205)) or Palette.SubText
      local tag = si and ("[" .. si .. "]  ") or ""
      local btn = New("TextButton", {
        Text = "  " .. tag .. "[" .. entry.kind .. "] " .. entry.path,
        Font = Enum.Font.GothamMedium,
        TextSize = 10,
        TextColor3 = col,
        BackgroundColor3 = bg,
        Size = UDim2.new(1, 0, 0, 30),
        AutoButtonColor = false,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextWrapped = true,
        Parent = frame,
      })
      Round(btn, 10)
      Stroke(btn, si and Color3.fromRGB(190, 190, 190) or Palette.StrokeSoft, 1, si and 0.45 or 1)
      table.insert(v2State.remoteListBtns, btn)
      SafeConnect(GetSignal(btn, "MouseButton1Click"), function()
        PlayUISound("Click")
        local slot = _getSlot(entry.remote)
        if slot then
          table.remove(v2State.selected, slot)
        else
          if #v2State.selected < 2 then
            table.insert(v2State.selected, entry.remote)
          else
            v2State.selected[2] = entry.remote
          end
        end
        V2RefreshRemoteList()
        local names = {}
        for _, r in ipairs(v2State.selected) do
          local ok, n = pcall(function() return r.Name
        end
        )
        if ok then
          table.insert(names, n)
        end
      end
      if v2State.selectedRemoteLbl then
        v2State.selectedRemoteLbl.Text =
        "  Selected: " .. (#names > 0 and table.concat(names, " + ") or "none")
      end
      _v2HM_RebuildPianoSet()
    end
    )
  end
  end
  local V2_PIANO_KW = {"piano", "keyboard", "key"}
  local V2_SEAT_RADIUS = 80
  local v2FoundPianos = {}
  local v2PianoListBtns = {}
  local v2ActivePianoSeat = nil
  local function V2ScanPianos()
    v2FoundPianos = {}
    local ws = game:GetService("Workspace")
    local allDesc = ws:GetDescendants()
    local seenModel = {}
    local function _addPiano(pos, displayName, sourceTag)
      for _, ex in ipairs(v2FoundPianos) do
        if (ex.pianoPos - pos).Magnitude < 5 then
          return
        end
      end
      local function _findNearestSeat(pianoPos, desc)
        local SEAT_NAME_KW = {"bench","seat","stool","chair","sofa","throne","pew"}
        local bestPart, bestDist = nil, V2_SEAT_RADIUS
        for _, obj in ipairs(desc) do
          local isSeat = obj:IsA("Seat") or obj:IsA("VehicleSeat")
          if not isSeat then
            local nl = obj.Name:lower()
            for _, kw in ipairs(SEAT_NAME_KW) do
              if nl:find(kw, 1, true) then
                isSeat = true;
                break
              end
            end
          end
          if isSeat then
            local bp = obj:IsA("BasePart") and obj
            or (obj:IsA("Model") and (obj.PrimaryPart or obj:FindFirstChildWhichIsA("BasePart")))
            if bp then
              local d = (bp.Position - pianoPos).Magnitude
              if d < bestDist then
                bestDist = d;
                bestPart = bp
              end
            end
          end
        end
        return bestPart, bestDist
      end
      local seatPart, seatDist = _findNearestSeat(pos, allDesc)
      local lbl = displayName
      .. "  [" .. math.floor(pos.X) .. "," .. math.floor(pos.Y) .. "," .. math.floor(pos.Z) .. "]"
      .. "  <" .. sourceTag .. ">"
      table.insert(v2FoundPianos, {
        name = displayName,
        pianoPos = pos,
        seatPart = seatPart,
        seatDist = seatDist,
        label = lbl,
      })
    end
    local gpc = workspace:FindFirstChild("GlobalPianoConnector")
    if gpc and gpc.Parent then
      pcall(function()
        local pp = gpc.Parent:IsA("BasePart") and gpc.Parent
        or (gpc.Parent:IsA("Model") and (gpc.Parent.PrimaryPart or gpc.Parent:FindFirstChildWhichIsA("BasePart")))
        if pp then
          _addPiano(pp.Position, gpc.Parent.Name, "GPC")
        end
      end
      )
    end
    for _, obj in ipairs(allDesc) do
      if obj:IsA("Model") and not seenModel[obj] then
        pcall(function()
          local hit = false
          local nl = obj.Name:lower()
          for _, kw in ipairs(V2_PIANO_KW) do
            if nl:find(kw, 1, true) then
              hit = true;
              break
            end
          end
          if not hit then
            for _, child in ipairs(obj:GetChildren()) do
              local cn = child.Name:lower()
              for _, kw in ipairs(V2_PIANO_KW) do
                if cn:find(kw, 1, true) then
                  hit = true;
                  break
                end
              end
              if hit then
                break
              end
            end
          end
          if hit then
            seenModel[obj] = true
            local bp = obj.PrimaryPart or obj:FindFirstChildWhichIsA("BasePart")
            if bp then
              _addPiano(bp.Position, obj.Name, "MDL")
            end
          end
        end
        )
      end
    end
    for _, obj in ipairs(allDesc) do
      if obj:IsA("BasePart") or obj:IsA("MeshPart") then
        pcall(function()
          local hit = false
          local nl = obj.Name:lower()
          for _, kw in ipairs(V2_PIANO_KW) do
            if nl:find(kw, 1, true) then
              hit = true;
              break
            end
          end
          if hit then
            local parentModel = obj.Parent and obj.Parent:IsA("Model") and obj.Parent
            if parentModel and seenModel[parentModel] then
              return
            end
            local pos = obj.Position
            if pos then
              _addPiano(pos, obj.Name, "PART")
              if parentModel then
                seenModel[parentModel] = true
              end
            end
          end
        end
        )
      end
    end
    return v2FoundPianos
  end
  local function V2RefreshPianoList()
    if not v2State.pianoListFrame then
      return
    end
    for _, b in ipairs(v2PianoListBtns) do
      pcall(b.Destroy, b)
    end
    v2PianoListBtns = {}
    local frame = v2State.pianoListFrame
    if #v2FoundPianos == 0 then
      if v2State.selectedPianoLbl then
        v2State.selectedPianoLbl.Text = "  No piano found."
        v2State.selectedPianoLbl.TextColor3 = Color3.fromRGB(130, 130, 130)
      end
      return
    end
    if v2State.selectedPianoLbl then
      v2State.selectedPianoLbl.Text = "  " .. #v2FoundPianos .. " piano(s) found. Click to select."
      v2State.selectedPianoLbl.TextColor3 = Color3.fromRGB(200, 200, 200)
    end
    for i, entry in ipairs(v2FoundPianos) do
      local hasSeat = entry.seatPart ~= nil
      local seatInfo = hasSeat
      and ("seat ~" .. math.floor(entry.seatDist) .. " studs")
      or "no seat nearby"
      local btn = New("TextButton", {
        Text = "  [" .. i .. "] " .. entry.name .. "\n        " .. seatInfo,
        Font = Enum.Font.GothamMedium,
        TextSize = 9,
        TextColor3 = hasSeat and Palette.Text or Palette.SubText,
        BackgroundColor3 = Palette.Home.Tile,
        Size = UDim2.new(1, 0, 0, 36),
        AutoButtonColor = false,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextWrapped = true,
        Parent = frame,
      })
      Round(btn, 10)
      Stroke(btn, hasSeat and Palette.StrokeSoft or Palette.Border, 1, 1)
      table.insert(v2PianoListBtns, btn)
      local capEntry = entry
      local capBtn = btn
      SafeConnect(GetSignal(btn, "MouseButton1Click"), function()
        PlayUISound("Click")
        for _, b in ipairs(v2PianoListBtns) do
          pcall(function()
            b.BackgroundColor3 = Palette.Home.Tile
            b.TextColor3 = Palette.SubText
          end
          )
        end
        capBtn.BackgroundColor3 = Palette.Btn.Active
        capBtn.TextColor3 = Palette.Text
        if capEntry.seatPart and capEntry.seatPart.Parent then
          v2ActivePianoSeat = capEntry.seatPart
          if v2State.selectedPianoLbl then
            v2State.selectedPianoLbl.Text = "  Selected: " .. capEntry.name
            .. " | Seat: " .. capEntry.seatPart.Name
            v2State.selectedPianoLbl.TextColor3 = Color3.fromRGB(220, 220, 220)
          end
          V2SetStatus("Piano selected: " .. capEntry.name, Color3.fromRGB(220, 220, 220))
        else
          v2ActivePianoSeat = nil
          if v2State.selectedPianoLbl then
            v2State.selectedPianoLbl.Text = "  Selected: " .. capEntry.name .. " (no seat)"
            v2State.selectedPianoLbl.TextColor3 = Color3.fromRGB(170, 170, 170)
          end
          V2SetStatus("Piano: " .. capEntry.name .. " (no seat found)", Color3.fromRGB(175, 175, 175))
        end
      end
      )
    end
  end
  local function V2DoTPAndSit()
    local ok, err = pcall(function()
      local char = LocalPlayer and LocalPlayer.Character
      if not char then
        error("No character")
      end
      local hrp = char:FindFirstChild("HumanoidRootPart")
      local hum = char:FindFirstChildOfClass("Humanoid")
      if not hrp or not hum then
        error("No HRP/Humanoid")
      end
      if not v2ActivePianoSeat then
        error("Select a piano from the list first")
      end
      hrp.CFrame = CFrame.new(v2ActivePianoSeat.Position + Vector3.new(0, 3, 0))
      local t0 = tick()
      while tick() - t0 < 0.25 do
        RunService.Heartbeat:Wait()
      end
      if v2ActivePianoSeat:IsA("Seat") or v2ActivePianoSeat:IsA("VehicleSeat") then
        v2ActivePianoSeat:Sit(hum)
      end
    end
    )
    if not ok then
      V2SetStatus("TP failed: " .. tostring(err), Color3.fromRGB(200, 80, 80))
    else
      V2SetStatus("Teleported & seated.", Color3.fromRGB(200, 200, 200))
    end
  end
  local v2RespawnPos = nil
  local v2RespawnCFrame = nil
  local function V2ScanRespawnPoints()
    local results = {}
    local ws = game:GetService("Workspace")
    local char = LocalPlayer and LocalPlayer.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local origin = hrp and hrp.Position or Vector3.new(0, 0, 0)
    for _, obj in ipairs(ws:GetDescendants()) do
      if obj:IsA("SpawnLocation") then
        local d = (obj.Position - origin).Magnitude
        table.insert(results, {
          part = obj,
          dist = d,
          label = obj.Name
          .. "  [" .. math.floor(obj.Position.X)
          .. "," .. math.floor(obj.Position.Y)
          .. "," .. math.floor(obj.Position.Z) .. "]",
        })
      end
    end
    table.sort(results, function(a, b) return a.dist < b.dist
  end
  )
  return results
  end
  local function V2TeleportToRespawn()
    if not v2RespawnPos then
      V2SetStatus("Scan spawn point first!", Color3.fromRGB(200, 80, 80))
      return
    end
    local ok, err = pcall(function()
      local char = LocalPlayer and LocalPlayer.Character
      if not char then
        error("No character")
      end
      local hrp = char:FindFirstChild("HumanoidRootPart")
      if not hrp then
        error("No HRP")
      end
      if v2RespawnCFrame then
        hrp.CFrame = v2RespawnCFrame + Vector3.new(0, 3, 0)
      else
        hrp.CFrame = CFrame.new(v2RespawnPos + Vector3.new(0, 3, 0))
      end
    end
    )
    if ok then
      V2SetStatus("Teleported to spawn.", Color3.fromRGB(200, 200, 200))
    else
      V2SetStatus("Spawn TP failed: " .. tostring(err), Color3.fromRGB(200, 80, 80))
    end
  end
